style.css:
@-moz-document domain("github.com") {
/* Fondo general y áreas de contenido */
body, 
.application-main, 
.bg-canvas-default, 
.bg-default,
[data-color-mode="dark"][data-dark-theme="dark"] {
    background-color: #1f1f28 !important; /* Sumi Ink 1 */
    color: #dcd7ba !important;           /* Old White */
}

/* Header / Barra de navegación superior */
header.Header, 
.Header-item {
    background-color: #16161d !important; /* Sumi Ink 0 */
    border-bottom: 1px solid #363646 !important;
}

/* Cajas, comentarios y contenedores de código */
.Box, 
.Box-header,
.timeline-comment, 
.discussion-timeline-actions,
.blankslate,
.Subnav-item--selected {
    background-color: #2a2a37 !important; /* Sumi Ink 2 */
    border: 1px solid #363646 !important;
    color: #dcd7ba !important;
}

/* Enlaces y Títulos (Acento azul Kanagawa) */
a, 
.Link--primary, 
.markdown-body h1, 
.markdown-body h2,
.f3.text-bold {
    color: #7e9cd8 !important; /* Crystal Blue */
}

/* Botones Principales (Violeta Kanagawa) */
.btn-primary,
.Button--primary {
    background-color: #938aa9 !important; /* Oni Violet */
    border-color: #938aa9 !important;
    color: #1f1f28 !important;
}

/* Sintaxis de Código (Kanagawa Wave) */
.pl-s  { color: #98bb6c !important; } /* Strings: Autumn Green */
.pl-k  { color: #957fb8 !important; } /* Keywords: Oni Violet */
.pl-en { color: #7e9cd8 !important; } /* Functions: Crystal Blue */
.pl-c  { color: #727169 !important; } /* Comments: River Gray */
.pl-v  { color: #ffa066 !important; } /* Variables: Surimi Orange */

/* Bordes y divisores generales */
* {
    border-color: #363646 !important;
  }
}
